 function simField(key,label,help=''){const [min,max,integer]=S.limits[key];return `<label class="field">${label}<input type="number" name="${key}" data-param="${key}" value="${params[key]}" min="${min}" max="${max}" step="${integer?'1':'any'}">${help?`<small>${help}</small>`:''}</label>`;}
 function simSelect(key,label,options){return select(key,label,String(params[key]),options,`data-param="${key}"`);}
 function simCard(number,title,body){return `<section class="panel form-card"><div class="panel-head"><h2>${title}</h2><span>${number}</span></div><div class="fields">${body}</div></section>`;}
 function simulator(){return heading('SIMULAR ANTES DE EXECUTAR','Enxergue o fluxo inteiro.','O modelo antigo, reorganizado: premissas à vista, fluxo detalhado antes dos gráficos e cada mês explicado.',btn('Salvar cenário','save-scenario')+btn('Exportar fluxo','export-flow')+btn('Usar como plano de referência','freeze','primary'))+`<div class="filter-row"><div><strong>${esc(scenarioName)}</strong><p class="caption">Rascunho independente de ${esc(baseline.id)} · mudanças recalculam automaticamente.</p></div><div class="actions">${btn('Meus cenários','scenarios')}<span id="sim-status" class="sim-saved">${isQA?'Sessão isolada de teste':'Salvamento local'}</span></div></div><div id="sim-safety">${safetyStrip()}</div><div id="sim-capacity" class="notice gap">Com esse capital, cabem até <strong>${report.capacityNow} carro(s)</strong> na aquisição inicial, preservando a reserva e os custos de preparação. Sua configuração pede ${params.initialFleet}.</div><form id="sim-form"><div class="grid3 sim-form">${simCard('01','Seu capital',simField('initialCapital','Capital disponível · R$')+simField('reserveFixed','Reserva de segurança · R$')+simField('companySetup','Abertura da empresa · R$')+simField('reservePerCar','Reserva adicional por carro · R$')+simField('initialFleet','Carros iniciais')+simField('targetFleet','Objetivo de frota'))}${simCard('02','Compra e financiamento',simSelect('financed','Forma de aquisição',[['true','Financiado · Price'],['false','À vista']])+simField('price','Preço do carro · R$')+input('downAmount','Entrada por carro · R$',S.round(params.price*params.downPct/100),'type="number" min="0" step="any" data-entry="true"')+input('loanAmount','Valor financiado · R$',S.round(params.financed?params.price*(1-params.downPct/100):0),'type="number" readonly data-loan-value="true"')+simField('term','Prazo · meses')+simField('monthlyRate','Juros · % ao mês'))}${simCard('03','Receita e utilização',simField('weekly','Aluguel semanal · R$')+simField('occupancy','Ocupação esperada · %')+simField('lossPct','Perda de recebimento · %')+simField('stoppedDays','Dias parados por mês')+simField('storeDaily','Vendas da loja por dia alugado · R$')+simField('horizon','Projetar por · meses'))}${simCard('04','Custo de cada carro',simField('insurance','Seguro mensal · R$')+simField('maintenanceMonthly','Manutenção mensal · R$')+simField('annualTax','IPVA anual · R$')+simField('annualLicense','Licenciamento anual · R$')+simField('tracker','Rastreador mensal · R$')+simField('washing','Limpeza mensal · R$'))}${simCard('05','Crescer ou amortizar',simSelect('reinvest','Reinvestir para crescer',[['true','Sim · preservar reserva'],['false','Não · manter caixa']])+simField('maxPurchasesPerMonth','Máximo de compras por mês')+simSelect('amortStrategy','Amortização extraordinária',[['off','Nunca'],['afterGoal','Caixa livre após a meta'],['monthly','Todo mês'],['sixMonths','A cada 6 meses'],['once','Evento escolhido']])+simField('extraAmort','Valor por evento · R$')+simField('extraMonth','Mês do evento único')+simSelect('priority','Primeiro usar o caixa para',[['growth','Comprar carro'],['debt','Amortizar dívida']]))}${simCard('06','Empresa e patrimônio',simField('admin','Administração / contador · R$ por mês')+simField('cashYieldAnnual','Rendimento do caixa · % ao ano')+simField('depreciationPct','Depreciação · % ao mês')+simField('profitTaxPct','IR sobre lucro positivo · %')+simField('monthlyContribution','Aporte mensal · R$')+simField('ownerDrawPct','Retirar do fluxo livre · %'))}</div><details class="sim-advanced"><summary>Detalhar preparação, loja, tributos, custos por km e aportes pontuais</summary><div class="fields">${simField('setup','Preparação por carro · R$')}${simField('financingFees','Tarifas de financiamento · R$')}${simField('stockCapital','Kit inicial por carro · custo R$')}${simField('centralStockCapital','Estoque central inicial · custo R$')}${simField('kmPerDay','Km por dia alugado')}${simField('maintenanceKm','Manutenção adicional por km · R$','Soma à provisão mensal; deixe zero se ela já cobre o custo.')}${simField('tiresKm','Pneus por km · R$')}${simField('other','Outros custos mensais por carro · R$')}${simField('staffThreshold','Equipe adicional a partir de · carros')}${simField('staffCost','Custo mensal da equipe · R$')}${simField('revenueTaxPct','Tributos sobre faturamento · %')}${simField('cogsPct','Custo da mercadoria · % das vendas')}${simField('commissionPct','Comissão da loja · % das vendas')}${simField('paymentFeePct','Taxa de pagamento · % das vendas')}${simField('storeLossPct','Perdas da loja · % das vendas')}${simField('oneOffContribution','Aporte pontual · R$')}${simField('contributionMonth','Mês do aporte pontual')}${simField('annualRentIncrease','Reajuste anual do aluguel · %')}${simField('annualCostInflation','Inflação anual dos custos · %')}${simField('startYear','Ano inicial')}${simField('startMonth','Mês inicial · 1 a 12')}</div></details><div id="sim-error" class="form-error" role="alert" hidden></div></form><div id="sim-results">${simulatorResults()}</div>`;}
 function safetyStrip(){const d=report.decision;return `<div class="safety-strip"><div><small>OCUPAÇÃO PARA EQUILIBRAR O CAIXA</small><strong>${pct(d.occupancyMin)}</strong></div><div><small>ALUGUEL SEMANAL DE EQUILÍBRIO</small><strong>${money(d.weeklyMin)}</strong></div><div><small>PRIMEIRO MÊS ABAIXO DA RESERVA</small><strong>${d.reserveBreach===null?'Não ocorre':'Mês '+d.reserveBreach}</strong></div><div><small>PRIMEIRO CAIXA NEGATIVO</small><strong>${d.negative===null?'Não ocorre':'Mês '+d.negative}</strong></div></div>`;}
 function simulatorResults(){const r=report.result,d=report.decision,f=r.final,m=r.months[0],mid=r.months[Math.floor((r.months.length-1)/2)];return `${report.acquisitionGap>0?`<div class="notice amber gap"><strong>A compra inicial não cabe preservando a reserva.</strong> Você pediu ${params.initialFleet} carro(s), mas ${r.initial.cars.length} cabem. Faltam ${money(report.acquisitionGap)} para a configuração solicitada.</div>`:''}${section('O negócio em números','Primeiro mês operacional e posição no fim do horizonte, com bases identificadas.')}<div class="stats executive">${stat('Fluxo livre · primeiro mês',money(m.cashAfterDebt),'Após custos, tributos e parcela',true)}${stat('Lucro · primeiro mês',money(m.result),'Inclui juros e depreciação; principal não é despesa')}${stat('ROI · horizonte completo',pct(d.roi),'Lucro acumulado ÷ capital próprio aportado')}${stat('Recuperação econômica',d.resultPayback===null?'Além do horizonte':'Mês '+d.resultPayback,'Lucro acumulado alcança o aporte; não é saque')}${stat('Capital próprio aportado',money(f.capital),'Inicial + aportes do horizonte')}${stat('Caixa livre · primeiro mês',money(m.available),'Caixa de fechamento menos a reserva')}${stat('Patrimônio nos carros · final',money(f.assets-f.debt),'Valor estimado dos carros menos a dívida')}${stat('Retorno · primeiro mês',pct(report.monthReturnPct),'Lucro mensal ÷ capital aportado')}${stat('Valor da frota · final',money(f.assets),'Estimativa de depreciação, sem cotação')}${stat('Patrimônio total · final',money(f.equity),'Caixa + carros + kit estimado − dívida')}</div><div class="grid2">${panel('Quanto do seu dinheiro já se pagou?',row('Capital próprio aportado',money(f.capital))+row('Recuperação econômica pelo lucro',money(report.economicRecovered),'Lucro acumulado positivo limitado ao capital aportado.')+`<div class="progress" role="progressbar" aria-label="Recuperação econômica" aria-valuenow="${report.economicRecoveryPct??0}" aria-valuemin="0" aria-valuemax="100"><i style="width:${report.economicRecoveryPct??0}%"></i></div>`+row('Ainda falta recuperar economicamente',money(report.capitalNotEconomicallyRecovered))+row('Dinheiro efetivamente retirado',money(report.cashRecovered),'Retirada é fluxo ao proprietário; lucro retido permanece na empresa.'))}${panel('Amortização que acontece de verdade',row('Amortização extra no horizonte',money(r.totalExtra),'Somente o valor que coube após preservar a reserva.')+row('Juros pagos no horizonte',money(report.totalInterest))+row('Dívida ao final',money(f.debt))+row('Frota ao final',f.fleet+' de '+params.targetFleet+' carros',r.targetMonth===null?'Objetivo não atingido dentro do horizonte.':'Meta atingida no mês '+r.targetMonth)+row('Folga de parada · primeiro mês',d.daysMargin===null?'Sem base':num(d.daysMargin)+' dias','Equivalência de caixa mantidas as demais premissas.'))}</div>${section('Fluxo detalhado','Leia a conta antes do gráfico. Hoje → operação → dívida → resultado → caixa.',segments([['annual','Ano a ano'],['monthly','Mês a mês']],flowMode,'flow-mode'))}${flowTable()}${section('A evolução do negócio','Os mesmos valores do fluxo, vistos ao longo do tempo.')}<div class="grid2">${chart('sim-cashflow','Fluxo da operação, mês a mês',['Entradas','Despesas','Parcela','Lucro'],'Entradas incluem aluguel recebido e loja. Despesas excluem a parcela; juros e principal continuam discriminados na tabela.')}${chart('sim-assets','Quanto os carros valem e quanto ainda devem',['Valor dos carros','Dívida','Patrimônio nos carros'])}</div><div class="grid2 gap">${chart('sim-cash','Evolução do caixa e da reserva',['Caixa de fechamento','Reserva mínima'],'Compras e amortizações extraordinárias só acontecem quando preservam a reserva. A própria operação deficitária pode consumi-la.')}${chart('sim-equity','Patrimônio construído e capital próprio',['Patrimônio total','Capital aportado'])}</div><div class="gap">${chart('sim-fleet','Quando cada novo carro entra na frota',['Frota ao fim do mês'],'A compra aparece no fechamento; o carro só passa a gerar receita no mês seguinte.')}</div>${section('Patrimônio em três momentos','Caixa, ativos e dívida em posições comparáveis.')}<div class="grid3">${[['Hoje',report.initial],['Meio do caminho · '+mid.label,mid],['Fim do plano · '+f.label,f]].map(([label,pos])=>panel(label,row('Carros',String(pos.fleet))+row('Valor dos carros',money(pos.assets))+row('Saldo devedor',money(pos.debt))+row('Caixa',money(pos.cash))+row('Patrimônio total',money(pos.equity),'Inclui kit estimado.',true))).join('')}</div>${section('Amortizar ou comprar o próximo?','Mesmo capital, premissas e horizonte. Estratégias determinísticas, sem nota subjetiva de risco.')}${panel('Uso do capital',table(['Estratégia','Frota final','Juros totais','Caixa','Dívida','Patrimônio'],d.alternatives.map(a=>`<tr><td>${a.name}</td><td>${a.result.final.fleet}</td><td>${money(a.interest)}</td><td>${money(a.result.final.cash)}</td><td>${money(a.result.final.debt)}</td><td>${money(a.result.final.equity)}</td></tr>`).join(''))+'<p class="caption">“Amortizar” prioriza a dívida com '+money(params.extraAmort)+'/mês. “Comprar” reinveste sem extra. “Manter” não expande nem faz amortização extra.</p>')}${section('Comprar agora ou esperar?','Uma compra adicional. Todas as alternativas terminam no mesmo horizonte de 24 meses.')}<div class="grid3">${T.purchaseTiming(params).map(o=>panel(o.wait===0?'Comprar agora':'Esperar '+o.wait+' meses',tag(o.viable?'Entrada + reserva cabem':'Ainda não cabe',o.viable?'green':'amber')+row('Falta para entrada e reserva',money(o.gap))+row('Caixa no horizonte',money(o.cash))+row('Patrimônio no horizonte',money(o.equity),'Sem outras aquisições durante a comparação.'))).join('')}</div>${section('Linha do tempo completa','Todos os meses, sem trocar de tela. Clique no período para abrir a memória de cálculo.')}<div class="month-cards">${report.monthly.map(m=>`<section class="month-card ${m.purchases?'purchase':''}"><strong>${link(m.label+' · mês '+m.month,'month-detail',`data-month="${m.month}"`)}</strong>${m.purchases?tag('+'+m.purchases+' carro(s)','green'):''}${row('Entradas',money(m.income))}${row('Pagamentos',money(m.paid))}${row('Lucro',money(m.result))}${m.purchases?row('Compras',money(m.capex)):''}${row('Caixa final',money(m.cash))}${row('Frota',m.fleet+' carros')}</section>`).join('')}</div><details class="sim-advanced"><summary>Estudar venda e renovação do veículo</summary><p class="caption">Estudo especializado do legado: um carro hipotético, preço de venda informado, sem depreciação, loja ou tributos. Não representa venda real da frota.</p><div class="form-actions">${btn('Abrir estudo de renovação','renewal')}</div></details><div class="notice gap">${r.warnings.length?r.warnings.map(w=>esc(w)).join('<br>'):'Nenhum caixa negativo ou quebra de reserva no horizonte, sob as premissas informadas.'} Custos, tributos e valor dos ativos são estimativas de planejamento. Esta projeção não executa compras nem financiamentos.</div>`;}
 function flowTable(){const rows=[report.initial,...(flowMode==='annual'?report.annual:report.monthly)];return panel('Operação → financiamento → resultado → caixa',`<div class="table-wrap"><table class="flow-table"><thead><tr>${P.columns.map(([,label])=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${rows.map(m=>`<tr class="${m.month===0?'initial':m.available<0?'below':m.purchases?'purchase':''}">${P.columns.map(([key])=>`<td class="${key==='label'?'':'numeric'}">${key==='label'?(m.month===0?'Hoje · antes da operação':flowMode==='annual'?m.label+(m.monthsCount<12?' · '+m.monthsCount+' meses':''):link(m.label+' · M'+m.month,'month-detail',`data-month="${m.month}"`)):m[key]===null?'—':['fleet','purchases'].includes(key)?num(m[key]):cash(m[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="caption">Tabela completa: role horizontalmente para conferir todas as colunas. Parcela = juros + amortização programada. Amortização total = programada + extra. Principal não é despesa; a depreciação reduz lucro, mas não sai do caixa. Entradas incluem vendas brutas da loja; despesas incluem mercadoria, comissão, taxas, perdas e tributos de faturamento. Ano parcial mostra quantos meses contém; caixa, frota e dívida são saldos finais, nunca soma de saldos.</p>`,btn('Exportar esta tabela','export-flow'));}
 function readSimulator(){const form=root.querySelector('#sim-form');if(!form)return;const next={...params};form.querySelectorAll('[data-param]').forEach(e=>{const key=e.dataset.param;next[key]=['financed','reinvest'].includes(key)?e.value==='true':['amortStrategy','priority'].includes(key)?e.value:Number(e.value);});let entry=Number(form.querySelector('[data-entry]').value);if(!next.financed){entry=next.price;form.querySelector('[data-entry]').value=entry;}const error=root.querySelector('#sim-error');try{if(!Number.isFinite(entry)||entry<0||entry>next.price)throw new RangeError('A entrada precisa ficar entre zero e o preço do carro.');next.downPct=next.price>0?entry/next.price*100:0;const valid=S.validate(next),nextReport=P.report(valid);params=valid;report=nextReport;revision=null;error.hidden=true;form.querySelector('[data-loan-value]').value=S.round(params.financed?params.price-entry:0);updateSimulatorResults();const saved=persist(),status=root.querySelector('#sim-status');if(status)status.textContent=isQA?'Recalculado · sessão de teste':saved?'Salvo neste navegador':'Não foi possível salvar';}catch(err){error.hidden=false;error.textContent=err.message;}}
 function updateSimulatorResults(){const results=root.querySelector('#sim-results'),safety=root.querySelector('#sim-safety');if(!results)return;results.innerHTML=simulatorResults();safety.innerHTML=safetyStrip();root.querySelector('#sim-capacity').innerHTML=`Com esse capital, cabem até <strong>${report.capacityNow} carro(s)</strong> na aquisição inicial, preservando reserva e preparação. Sua configuração pede ${params.initialFleet}.`;drawCharts();}
 function simulatorAction(action,e){
  if(action==='month-detail'){const m=report.result.months.find(m=>m.month===Number(e.dataset.month));open('Memória de cálculo · '+m.label,P.bridge(m).map(([label,value],i)=>row(label,cash(value),'',i===13)).join('')+row('Juros dentro da parcela',cash(m.interest))+row('Principal dentro da parcela',cash(m.scheduledPrincipal))+row('Depreciação sem saída de caixa',cash(m.depreciation))+row('Lucro líquido do mês',cash(m.result))+`<p class="caption">Diferença da identidade de caixa: ${cash(m.bridgeError)}. Todos os valores vêm do mesmo motor, sem recalcular na tela.</p>`);return true;}
  if(action==='save-scenario'){open('Salvar cenário independente',`<form id="scenario-form">${input('name','Nome do cenário',scenarioName,'required maxlength="100"')}<div class="form-actions"><button type="submit" class="btn primary">Preservar esta cópia</button></div></form>`);return true;}
  if(action==='scenarios'){open('Seus cenários',savedScenarios.length?table(['Cenário','Horizonte','Ações'],savedScenarios.map((s,i)=>`<tr><td>${esc(s.name)}<small>${esc(new Date(s.at).toLocaleString('pt-BR'))}</small></td><td>${s.params.horizon} meses</td><td>${btn('Carregar cópia','load-scenario','',`data-index="${i}"`)} ${btn('Excluir cópia','delete-scenario','',`data-index="${i}"`)}</td></tr>`).join('')):'<p class="caption">Use “Salvar cenário” para preservar uma cópia antes de testar outra hipótese.</p>');return true;}
  if(action==='load-scenario'){const s=savedScenarios[Number(e.dataset.index)];params=S.validate(structuredClone(s.params));scenarioName=s.name;page='simulator';mode='admin';close();render();persist();return true;}
  if(action==='delete-scenario'){savedScenarios.splice(Number(e.dataset.index),1);close();persist();toast('Cópia removida dos cenários locais.');return true;}
  if(action==='export-flow'){download('rodavolt-fluxo-'+(flowMode==='annual'?'anual':'mensal')+'.csv',P.csv([report.initial,...(flowMode==='annual'?report.annual:report.monthly)]),'text/csv;charset=utf-8');return true;}
  if(action==='renewal'){open('Estudar a renovação',`<form id="renewal-form"><div class="fields">${input('value','Valor estimado da venda · R$',55000,'type="number" min="0" step=".01" required')}${input('fee','Custos de venda · %',3,'type="number" min="0" max="100" step="any" required')}</div><p class="caption">Compara vender em até 12 datas trimestrais com manter até o final. Valor de venda é sua hipótese, sem cotação automática.</p><div class="form-actions"><button type="submit" class="btn primary">Comparar manter e vender</button></div></form>`);return true;}
  return false;
 }
 function simulatorSubmit(form,f){if(form.id==='scenario-form'){const name=String(f.get('name')).trim();if(!name)throw new RangeError('Informe o nome do cenário.');scenarioName=name;savedScenarios.push({name,params:structuredClone(params),at:new Date().toISOString()});close();render();persist();toast('Cenário preservado. O plano de comparação não foi alterado.');return true;}
 if(form.id==='renewal-form'){const e=T.validateExpansion({...T.defaults().expansion,price:params.price,entry:params.financed?params.price*params.downPct/100:params.price,rate:params.monthlyRate,term:params.term,weekly:params.weekly,occupancy:params.occupancy,insurance:params.insurance,annualTax:params.annualTax,tracker:params.tracker,maintenance:params.maintenanceKm+params.tiresKm,km:params.kmPerDay*28,admin:params.admin,reserve:params.reserveFixed,horizon:params.horizon,saleValue:Number(f.get('value')),saleFee:Number(f.get('fee'))}),r=T.renewal(e);open('Manter ou vender · mesmo horizonte',`<div class="notice">Melhor entre as hipóteses: <strong>${r.best.mesVenda===null?'manter':'vender no mês '+r.best.mesVenda}</strong>. Patrimônio final de ${money(r.best.patrimonioFinalNoHorizonte)}.</div>`+table(['Venda','Caixa final','Dívida','Patrimônio','Capital reciclado','Frota'],r.porMomento.map(m=>`<tr><td>${m.mesVenda===null?'Manter':'Mês '+m.mesVenda}</td><td>${money(m.caixaFinal)}</td><td>${money(m.meses.at(-1).saldoDevedor)}</td><td>${money(m.patrimonioFinalNoHorizonte)}</td><td>${money(m.capitalReciclado)}</td><td>${m.frotaFinalUnidades}</td></tr>`).join(''))+`<p class="caption">Modelo especializado do legado: valor dos veículos constante, sem depreciação, loja ou tributos. Não compare diretamente com o patrimônio do modelo empresarial completo. Venda abaixo da dívida mostra a diferença negativa.</p>`);return true;}return false;}
